func (c *Client) cacheKey(path string, params map[string]string) string {
	key := path
	key += "|base_url=" + c.BaseURL
	if c.Config != nil {
		key += "|auth_source=" + c.Config.AuthSource
		if authHeader := c.Config.AuthHeader(); authHeader != "" {
			authHash := sha256.Sum256([]byte(authHeader))
			key += "|auth=" + hex.EncodeToString(authHash[:8])
		}
		if c.Config.Path != "" {
			key += "|config_path=" + c.Config.Path
		}
	}
	paramKeys := make([]string, 0, len(params))
	for k := range params {
		paramKeys = append(paramKeys, k)
	}
	sort.Strings(paramKeys)
	for _, k := range paramKeys {
		key += k + "=" + params[k]
	}
	h := sha256.Sum256([]byte(key))
	return hex.EncodeToString(h[:8])
}

// srmPathTTL returns a context-appropriate cache TTL for each SRM resource path.
// Router telemetry (traffic, utilization) expires quickly; configuration data
// (wifi, firewall, qos, dns) can be cached much longer.
func srmPathTTL(path string) time.Duration {
	switch {
	case strings.HasPrefix(path, "/traffic"):
		return 15 * time.Second // live bandwidth — very short-lived
	case strings.HasPrefix(path, "/utilization"):
		return 20 * time.Second // CPU/memory counters — near real-time
	case strings.HasPrefix(path, "/devices"):
		return 30 * time.Second // device presence — changes as devices join/leave
	case strings.HasPrefix(path, "/wan"):
		return 60 * time.Second // WAN status — stable but reconnects happen
	case strings.HasPrefix(path, "/mesh"):
		return 60 * time.Second // mesh node status — changes on disconnect
	case strings.HasPrefix(path, "/wifi"):
		return 5 * time.Minute // Wi-Fi settings — rarely reconfigured
	case strings.HasPrefix(path, "/qos"):
		return 5 * time.Minute // QoS rules — rarely reconfigured
	case strings.HasPrefix(path, "/firewall"):
		return 5 * time.Minute // Firewall rules — rarely reconfigured
	case strings.HasPrefix(path, "/smartwan"):
		return 5 * time.Minute // Smart WAN config — rarely reconfigured
	case strings.HasPrefix(path, "/wol"):
		return 5 * time.Minute // WOL device registry — rarely changes
	case strings.HasPrefix(path, "/access-control"):
		return 5 * time.Minute // access control groups — rarely reconfigured
	case strings.HasPrefix(path, "/dns"):
		return 10 * time.Minute // DDNS records — very rarely changes
	case strings.HasPrefix(path, "/system"):
		return 60 * time.Minute // API info — static capability manifest
	default:
		return 5 * time.Minute
	}
}

func (c *Client) readCache(path string, params map[string]string) (json.RawMessage, bool) {
	cacheFile := filepath.Join(c.cacheDir, c.cacheKey(path, params)+".json")
	info, err := os.Stat(cacheFile)
	if err != nil || time.Since(info.ModTime()) > srmPathTTL(path) {
		return nil, false
	}
	data, err := os.ReadFile(cacheFile)
	if err != nil {
		return nil, false
	}
	return json.RawMessage(data), true
}

func (c *Client) writeCache(path string, params map[string]string, data json.RawMessage) {
	os.MkdirAll(c.cacheDir, 0o755)
	cacheFile := filepath.Join(c.cacheDir, c.cacheKey(path, params)+".json")
	os.WriteFile(cacheFile, []byte(data), 0o644)
}

// invalidateCache wholesale-removes the cache directory so the next read
// after a mutation cannot return a stale snapshot. Selective per-resource
// invalidation rejected: cache keys are opaque sha256 hashes.
func (c *Client) invalidateCache() {
	if c.cacheDir == "" {
		return
	}
	_ = os.RemoveAll(c.cacheDir)
}

